// A teammate value-imported and value-re-exported the type.
import { Booking, makeBooking, VERSION } from './model.ts';
export { Booking };
export function describe(b: Booking): string { return b.lab + ' v' + VERSION; }
export const demo = makeBooking(1, 'BE-201');

export type Booking = { id: number; lab: string };
export type Lab = { code: string };
export const makeBooking = (id: number, lab: string): Booking => ({ id, lab });
export const VERSION = 1;

import type { Booking } from '../src/boundary.ts';
import { describe, demo } from '../src/boundary.ts';
const b: Booking = { id: 1, lab: 'BE-201' };
export const text: string = describe(b);
export { demo };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { describe, demo } from '../src/boundary.ts';
test('the boundary runs after types are erased', () => { assert.equal(demo.lab, 'BE-201'); assert.equal(describe({ id: 2, lab: 'CS-101' }), 'CS-101 v1'); });

